import { useQuery } from '@tanstack/react-query';
import { api } from '@/shared/api/client';
import { apiData, apiEnvelope } from '@/shared/api/request';
import { reportsKeys } from './keys';
import { pollInterval } from './polling';
import type {
  FileAccess,
  Limits,
  Report,
  ReportInput,
  ReportList,
  ReportSchedule,
  ScheduleInput,
  SchedulePatch,
} from './types';

function signalOption(signal?: AbortSignal) {
  return signal ? { signal } : {};
}

/**
 * Reports and exports (spec §4.11, §20B.12). Reports are generated by a
 * background job from a stored filter snapshot; files are private and are
 * downloaded through short-lived signed links.
 */
export const reportsApi = {
  list: async (signal?: AbortSignal): Promise<ReportList> => {
    const envelope = await apiEnvelope(api.GET('/reports', signalOption(signal)));
    return { reports: envelope.data, serverTime: envelope.meta.timestamp };
  },
  create: (body: ReportInput): Promise<Report> => apiData(api.POST('/reports', { body })),
  /** Deletes a report in any status (a running generation is cancelled; its file is removed). */
  remove: (id: string): Promise<{ ok: boolean }> =>
    apiData(api.DELETE('/reports/{id}', { params: { path: { id } } })),
  /** A signed link (valid for minutes) to a completed report's file. */
  access: (id: string): Promise<FileAccess> =>
    apiData(api.GET('/reports/{id}/download', { params: { path: { id } } })),
  schedules: (signal?: AbortSignal): Promise<ReportSchedule[]> =>
    apiData(api.GET('/reports/schedules', signalOption(signal))),
  /** One schedule, e.g. its latest version after a concurrent change. */
  schedule: (id: string, signal?: AbortSignal): Promise<ReportSchedule> =>
    apiData(
      api.GET('/reports/schedules/{id}', { params: { path: { id } }, ...signalOption(signal) }),
    ),
  createSchedule: (body: ScheduleInput): Promise<ReportSchedule> =>
    apiData(api.POST('/reports/schedules', { body })),
  /** Edits, pauses (`enabled: false`) or resumes a schedule; `version` detects a concurrent change. */
  updateSchedule: (id: string, body: SchedulePatch): Promise<ReportSchedule> =>
    apiData(api.PATCH('/reports/schedules/{id}', { params: { path: { id } }, body })),
  deleteSchedule: (id: string): Promise<{ ok: boolean }> =>
    apiData(api.DELETE('/reports/schedules/{id}', { params: { path: { id } } })),
  /** Fair-use limits, including how long downloads stay available. */
  limits: (signal?: AbortSignal): Promise<Limits> =>
    apiData(api.GET('/limits', signalOption(signal))),
};

/** Recent reports; polls while one is being prepared (quickly at first, then slower). */
export function useReports() {
  return useQuery({
    queryKey: reportsKeys.list(),
    queryFn: ({ signal }) => reportsApi.list(signal),
    refetchInterval: (query) => pollInterval(query.state.data),
  });
}

export function useSchedules() {
  return useQuery({
    queryKey: reportsKeys.schedules(),
    queryFn: ({ signal }) => reportsApi.schedules(signal),
  });
}

export function useLimits() {
  return useQuery({
    queryKey: reportsKeys.limits(),
    queryFn: ({ signal }) => reportsApi.limits(signal),
    staleTime: 60 * 60_000,
  });
}
